<?php require_once __DIR__.'/../../app/layout.php';$a=require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);if(($_POST['action']??'')==='delete')$pdo->prepare('DELETE FROM membership_types WHERE id=?')->execute([$id]);else{$v=[trim($_POST['name']),$_POST['fee'],trim($_POST['validity']),trim($_POST['description']??''),isset($_POST['is_active'])?1:0];if($id)$pdo->prepare('UPDATE membership_types SET name=?,fee=?,validity=?,description=?,is_active=? WHERE id=?')->execute([...$v,$id]);else $pdo->prepare('INSERT INTO membership_types (name,fee,validity,description,is_active) VALUES (?,?,?,?,?)')->execute($v);}flash('Membership type saved.');redirect('/admin/membership-types.php');}$e=['id'=>'','name'=>'','fee'=>'','validity'=>'1 Year','description'=>'','is_active'=>1];if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM membership_types WHERE id=?');$s->execute([(int)$_GET['edit']]);$e=$s->fetch()?:$e;}$rows=$pdo->query('SELECT * FROM membership_types ORDER BY name')->fetchAll();header_html('Membership types');?><style>.active-option{display:flex;align-items:center;gap:8px;margin:5px 0 18px}.active-option input{width:auto;margin:0}.membership-save{margin-top:0}</style><h1>Membership Types</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$e['id']?>"><label>Name<input name="name" value="<?=e($e['name'])?>" required></label><label>Fee<input type="number" name="fee" value="<?=e($e['fee'])?>" required></label><label>Validity<input name="validity" value="<?=e($e['validity'])?>" required></label><label>Description<textarea name="description"><?=e($e['description'])?></textarea></label><label class="active-option"><input type="checkbox" name="is_active" <?=$e['is_active']?'checked':''?>> <span>Active</span></label><button class="membership-save"><?= $e['id']?'Update Membership Type':'+ New Membership Type'?></button></form><table><tr><th>Name</th><th>Fee</th><th>Validity</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td>₹<?=e($r['fee'])?></td><td><?=e($r['validity'])?></td><td><a href="?edit=<?=$r['id']?>">Edit</a></td></tr><?php endforeach;?></table><?php footer_html();
